/*updateCommonMpIvAgrmntPors*/
UPDATE ICOMPORS
SET
	ADMIN_FLAG1 = 'Y'
WHERE
		BUYER = #{st_buyer}
	AND PO_NO = #{st_po_no}
	AND PO_SEQ = #{st_po_seq}

/*insertCommonMpIvAgrmntMailSend*/ INSERT INTO MAILSEND SELECT 'PMPA_DELIVERY_MB' AS MAILFORM_ID , 'M' AS SEND_COM_TYPE , 'B' AS RECV_COM_TYPE , 'KRKORE0001' AS SEND_COM_CODE , 'KOREAB2B' AS SEND_USER_ID , A.BUYER AS KEY1 , A.PO_NO AS KEY2 , A.PO_SEQ AS KEY3 , (SELECT NVL(MAX(SEQ),0)+1 FROM KEP_PO_DELY_MNG WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ) AS KEY4 , A.RECV_USER_ID AS KEY5 , ' ' AS KEY6 , ' ' AS KEY7 , ' ' AS KEY8 , ' ' AS KEY9 , ' ' AS KEY10 , SYSDATE AS CRE_DATE , '' AS ERR_DATE FROM ( SELECT D.BUYER , D.PO_NO , D.PO_SEQ , (SELECT PURCHASER_ID FROM ICOMPOHD WHERE BUYER = D.BUYER AND PO_NO = D.PO_NO) AS RECV_USER_ID FROM ICOMPODT D WHERE D.BUYER = #{st_buyer} AND D.PO_NO = #{st_po_no} AND D.PO_SEQ = #{st_po_seq}
UNION ALL
SELECT D.BUYER , D.PO_NO , D.PO_SEQ , (SELECT REQ_USER_ID FROM ICOMPRDT WHERE BUYER = D.BUYER AND PR_NO = D.PR_NO AND PR_SEQ = D.PR_SEQ) AS RECV_USER_ID FROM ICOMPODT D WHERE D.BUYER = #{st_buyer} AND D.PO_NO = #{st_po_no} AND D.PO_SEQ = #{st_po_seq} ) A GROUP BY A.BUYER, A.PO_NO, A.PO_SEQ, A.RECV_USER_ID
